shell_commands.command:
python3 - <<'PY'
from pathlib import Path
path = Path('test/xchar-test.cc')
text = path.read_text()
anchor = 'TEST(locale_test, format) {\n'
addition = '''TEST(locale_test, localized_double_alignment) {
  auto loc = std::locale(std::locale(), new numpunct<char>());
  struct test_case {
    double value;
    const char* expected;
  } cases[] = {{0.295, "0?295"},
               {1.295, "1?295"},
               {-119.921, "-119?921"},
               {2194.139, "2~194?139"},
               {-57.639, "-57?639"},
               {-5.980, "-5?980"},
               {-2.119, "-2?119"},
               {12.345, "12?345"},
               {123.456, "123?456"},
               {1234.567, "1~234?567"},
               {12345.678, "12~345?678"},
               {1234567.890, "1~234~567?890"}};
  for (auto c : cases) {
    auto expected = std::string(c.expected);
    EXPECT_EQ(std::string(19 - expected.size(), ' ') + expected,
              fmt::format(loc, "{:19.3Lf}", c.value));
  }
  EXPECT_EQ("1?295     ", fmt::format(loc, "{:<10.3Lf}", 1.295));
  EXPECT_EQ("__1?295___", fmt::format(loc, "{:_^10.3Lf}", 1.295));
  EXPECT_EQ("000001?295", fmt::format(loc, "{:010.3Lf}", 1.295));
  EXPECT_EQ("-00001?295", fmt::format(loc, "{:010.3Lf}", -1.295));
}

TEST(locale_test, localized_wide_double_alignment) {
  auto loc = std::locale(std::locale(), new numpunct<wchar_t>());
  EXPECT_EQ(L"     0?295", fmt::format(loc, L"{:10.3Lf}", 0.295));
  EXPECT_EQ(L"     1?295", fmt::format(loc, L"{:10.3Lf}", 1.295));
  EXPECT_EQ(L" 1~234?567", fmt::format(loc, L"{:10.3Lf}", 1234.567));
  EXPECT_EQ(L"1?295     ", fmt::format(loc, L"{:<10.3Lf}", 1.295));
  EXPECT_EQ(L"__1?295___", fmt::format(loc, L"{:_^10.3Lf}", 1.295));
  EXPECT_EQ(L"-00001?295", fmt::format(loc, L"{:010.3Lf}", -1.295));
}

'''
assert text.count(anchor) == 1
path.write_text(text.replace(anchor, addition + anchor))
PY
cmake -B build -S . && cmake --build build --parallel 4 --target xchar-test && build/bin/xchar-test --gtest_filter='locale_test.localized*alignment'

